def precondition(*args) -> bool:
    try:
        if len(args) != 1:
            return False
        n = args[0]
        fin = lambda x: isinstance(x, float) and math.isfinite(x)
        if not isinstance(n, list) or len(n) < 2 or not all(fin(x) for x in n):
            return False
        if any(abs(x) > 1e9 for x in n):
            return False
        best = None
        pairs = set()
        for i in range(len(n)):
            for j in range(i + 1, len(n)):
                a, b = sorted((n[i], n[j]))
                d = b - a
                if best is None or d < best:
                    best = d
                    pairs = {(a, b)}
                elif d == best:
                    pairs.add((a, b))
        return len(pairs) == 1
    except Exception:
        return False

